 "content": "from collections import Counter

def transform(grid):
    # Each 3x3 patch encodes its most frequent non-background color.
    out = []
    for br in range(0, len(grid), 3):
        row = []
        for bc in range(0, len(grid[0]), 3):
            patch = [grid[r][c] for r in range(br, min(br+3, len(grid))) for c in range(bc, min(bc+3, len(grid[0]))) ]
            counts = Counter(patch)
            row.append(max(counts, key=lambda x: (counts[x], x)))
        out.append(row)
    return out
